INSERT INTO job_roles (id, company_id, title, description) VALUES
('4b51d4ef-11e6-5785-98f0-15e6c7582500', 'e11e88cd-2fa1-5bdd-9528-e62a22123b07', 'Backend Developer', 'Build REST APIs in Python, design SQL schemas and write efficient queries. Docker and Git are a plus.'),
('ea030b8b-fe3e-5153-92b1-c4d5d9eb03c8', 'bf10ef1b-5bee-530e-b926-8645c5d3d98a', 'Data Analyst', 'Analyse transaction data with SQL and Excel, build Power BI dashboards, present findings.'),
('e64d84b2-9f9e-52dc-930d-126c4cb70bd1', '177870cb-b487-5df5-8efe-c6d2d686e912', 'Cloud Support Engineer', 'Support customer workloads on Linux and Docker; scripting and networking fundamentals expected.'),
('1ded209d-6288-5c3c-a94d-1862762cbf13', '084fe152-9887-501a-9713-edc585a7bfc4', 'Software Engineer Trainee', 'Strong data structures and Java; you will work on enterprise applications with SQL and Git.'),
('cde22da7-7301-5d2b-b720-a7901a68c40f', 'f5539349-3f5d-5796-828c-c1e85211a33f', 'ML Engineer Intern', 'Train and deploy crop-yield models in Python; pandas, scikit-learn, and Docker for serving.'),
('cdb1e990-13c0-5e2f-9930-dbf82b6da923', 'ad80b838-b5d1-59df-a711-4285cd3bf28f', 'Embedded Systems Engineer', 'Firmware in Embedded C for ARM microcontrollers; digital electronics and PCB debugging.'),
('a9deadb4-0895-5a89-830f-b5c48ca65ee9', 'd77364ae-83d9-5e12-a4ec-fd4b13a4fdf1', 'Design Engineer (GET)', 'Part and assembly modelling in SolidWorks and CATIA, GD&T, manufacturing drawings.'),
('5e08b5e4-84bc-54b2-8628-107c348c3b0a', '811b85f4-acba-5af6-82d5-f24fbeab21d0', 'Junior Site Engineer', 'Site supervision, AutoCAD drawings, quantity estimation and surveying.'),
('6782ff22-5351-5599-9b22-b971fab3a7d4', '9761b5bd-3967-52de-a8e9-92bbc4cc58ae', 'Solar Installation Technician', 'Install and commission rooftop solar PV; wiring, earthing and electrical safety.'),
('3aaf9c04-af89-573b-bf57-0774815eb292', '251fae3c-44c4-576a-aadd-cbc8ba17abeb', 'Associate Software Engineer (completed)', 'Healthcare software: Java or Python services and SQL. Completed drive used for funnel analytics.')
ON CONFLICT (id) DO NOTHING;

