INSERT INTO probe_definitions (id, skill_id, title, description, language, entry_function_name, test_harness_code, timeout_ms,
  student_id, commit_sha, file_path, line_start, line_end, code_span, content_hash, predict_question, predict_key_points, mutation_task, provenance)
SELECT '75a74356-d7d2-5391-bc1d-5b24778e5127'::uuid, s.id, 'Live Mutation Probe: cart pricing', 'Repository rahul-deshmukh/campus-canteen-app at commit 3f9c2a7', 'javascript', 'finalAmount',
  '[{"input":[[{"pricePaise":4000,"qty":2},{"pricePaise":2500,"qty":1}],10],"description":"normal cart with 10% discount","expected":9923},{"input":[[],0],"description":"empty cart","expected":0},{"input":[[{"pricePaise":4000,"qty":1}],120],"expectError":"RangeError","description":"discount above 100% is rejected"},{"input":[[{"pricePaise":4000,"qty":1}],-5],"expectError":"RangeError","description":"negative discount is rejected"},{"input":[[{"pricePaise":4000,"qty":0},{"pricePaise":1000,"qty":-1},{"pricePaise":3000,"qty":1}],0],"description":"zero and negative quantities ignored","expected":3150},{"input":[[{"pricePaise":999,"qty":3}],33],"description":"rounding of discount and GST","expected":2108}]', 2000, 'f5c42a09-b769-5e47-a18a-7490b0b64a30'::uuid, '3f9c2a7d1e8b4c6a9f0e2d1c3b5a7e9f1d2c4b6a', 'src/cart/pricing.js', 3, 13,
  '// Computes the amount payable for a cart, in paise: applies a percentage discount, then 5% GST.
// Used by the checkout screen of the canteen app.
function finalAmount(items, discountPercent) {
  let subtotal = 0;
  for (const item of items) {
    subtotal += item.pricePaise * item.qty;
  }
  const discount = Math.round(subtotal * discountPercent / 100);
  const taxable = subtotal - discount;
  const gst = Math.round(taxable * 5 / 100);
  return taxable + gst;
}', '1f98ae5fcc711ac3bdf33ef2fe6f87aaa75a24eb00b2487177894d26646eeec8', 'Look at finalAmount in your src/cart/pricing.js. What does it return for an empty cart, and what happens if discountPercent is 120? Is that acceptable at checkout?', '[{"point":"An empty cart returns 0","keywords":["returns 0","return 0","zero"," 0 "]},{"point":"A 120% discount makes the amount negative","keywords":["negative","less than zero","below zero","minus"]},{"point":"Discount must be validated or limited to 0–100","keywords":["validate","clamp","limit","between 0 and 100","0 to 100","check","throw","error"]}]'::jsonb,
  'Change finalAmount so that a discount below 0 or above 100 throws a RangeError, and items with a quantity of 0 or less are ignored. Everything else must behave as before.', 'preloaded_demo_snapshot'
FROM skills s WHERE s.slug = 'javascript'
ON CONFLICT (id) DO NOTHING;

